Outcome stage(u64 bytes) noexcept {
  bytes = bytes < kStagingMin ? kStagingMin : bytes < kStagingMax ? bytes : kStagingMax;
  if (staging_bytes >= bytes) return {};
  MHGP12_TRY(sync());
  if (staging != nullptr) cudaFreeHost(staging);
  staging = nullptr;
  staging_bytes = 0;
  staging_reservation.reset();
  MHGP12_TRY(staging_reservation.reserve(bytes, budget));
  const Outcome made = check(cudaMallocHost(reinterpret_cast<void**>(&staging), bytes));
  if (!made.ok()) {
    staging = nullptr;
    staging_reservation.reset();
    return made;
  }
  staging_bytes = bytes;
  ++allocations;
  return {};
}

inline void device_diagnostics(const TraversalDiagnostics& front, const DeviceTotals& t, const fin::FinishStats& f,
                               u64 traversal_ns, u64 upload_ns, CatalogueDiagnostics& d) noexcept {
  d.levels = front.levels;
  d.tasks = front.tasks;
  d.candidates = front.candidates;
  d.leaves_narrow = t.tiers[0];
  d.leaves_medium = t.tiers[1];
  d.leaves_wide = t.tiers[2];
  d.leaves_exact = t.tiers[3];
  d.leaves_virtual_warp = t.tiers[4];
  d.max_leaf_span = t.max_span;
  d.traversal_ns = traversal_ns - upload_ns - t.leaves_ns - t.emission_ns;  // parcours seul
  d.count_ns = t.leaves_ns;                                                 // feuilles
  d.fill_ns = t.emission_ns;                                                // emission
  d.levels_ns = f.keys_ns;
  d.sort_ns = f.sort_ns;
  d.assemble_ns = f.check_ns + f.emit_ns;
  d.transfer_ns = upload_ns + f.take_ns;
  d.table_ns = f.table_ns;
  d.chains_repaired = f.chains_repaired;
  d.chain_elements = f.chain_elements;
  d.batches = t.batches;
  d.replayed_leaves = t.replayed_leaves;
  d.replayed_balls = t.replayed_balls;
}

